#!/usr/bin/env node
/**
 * Translate the built panel's remaining English UI strings.
 *
 * The panel is a single minified HTML document (app.html) plus the browser host
 * page (browser-panel.html). Most of the copy lives in the engine sources and is
 * rebuilt from there, but strings the sources no longer carry (older builds,
 * strings generated by the runtime, and the "Mobile Dev" brand) are fixed here:
 * one glossary, applied to the two files that ship. Idempotent — a translated
 * file no longer contains the English keys, so a second run is a no-op.
 *
 * Run by `npm run build:panel` and by `prepack`, after the panel is built.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const dist = join(root, 'vendor', 'runtime', 'dist')
const targets = [join(dist, 'app.html'), join(dist, 'browser-panel.html')]

/** English UI copy → Chinese. Longest first so shorter keys cannot eat a prefix. */
const GLOSSARY = [
  ['Mobile Dev 已与其聊天会话断开。请让智能体重新打开 Mobile Dev。', '模拟器已与其聊天会话断开。请让智能体重新打开模拟器。'],
  ['Mobile Dev 的浏览器连接已过期。请重新加载此页面以重新连接。', '模拟器页面的连接已过期。请重新加载此页面。'],
  ['Mobile Dev 的面板无法加载。', '模拟器的面板无法加载。'],
  ['Mobile Dev 的浏览器连接尚未就绪。', '模拟器页面的连接尚未就绪。'],
  ['Mobile Dev could not share this with the chat', '模拟器无法把这份内容分享到对话'],
  ['This link does not open the Mobile Dev panel.', '这个链接不能打开模拟器面板。'],
  ['此链接不会打开 Mobile Dev 面板。', '此链接不会打开模拟器面板。'],
  ['Mobile Dev shows no device view here', '这里没有设备画面'],
  ['Mobile Dev has no panel for', '模拟器没有对应的面板：'],
  ['Mobile Dev', '模拟器'],
  ['Resize tools and simulators', '调整工具与模拟器区域大小'],
  ['Resize iOS and Android simulators', '调整 iOS 与 Android 模拟器大小'],
  ['Select and annotate components', '选择并标注组件'],
  ['Click an element or drag a region to add a note', '点击元素或拖动框选区域以添加备注'],
  ['Screenshot to chat and clipboard', '截图发送到聊天并复制到剪贴板'],
  ['Live simulator screen', '实时模拟器画面'],
  ['Opening the device screen.', '正在打开设备屏幕。'],
  ['Finding available iOS devices.', '正在查找可用的 iOS 设备。'],
  ['Finding available Android devices.', '正在查找可用的 Android 设备。'],
  ['Screen unavailable', '屏幕不可用'],
  ['Device stopped', '设备已停止'],
  ['Start device', '启动设备'],
  ['Connecting…', '正在连接…'],
  ['Connected devices', '已连接设备'],
  ['Connected', '已连接'],
  ['Simulators', '模拟器'],
  ['Developer tools', '开发者工具'],
  ['Visible platforms', '可见平台'],
  ['Device settings', '设备设置'],
  ['iOS simulator', 'iOS 模拟器'],
  ['Android simulator', 'Android 模拟器'],
  ['iOS controls', 'iOS 控制栏'],
  ['Android controls', 'Android 控制栏'],
  ['iOS device settings', 'iOS 设备设置'],
  ['Android device settings', 'Android 设备设置'],
  ['iOS device', 'iOS 设备'],
  ['Android device', 'Android 设备'],
  ['iOS screen. Click or drag to interact. Focus to type.', 'iOS 画面。点击或拖动即可操作，聚焦后可输入。'],
  ['Android screen. Click or drag to interact. Focus to type.', 'Android 画面。点击或拖动即可操作，聚焦后可输入。'],
  ['is unavailable on physical iOS devices', '在 iPhone 真机上不可用'],
  ['Too many physical device streams. Close another panel first.', '真机视频流太多了，请先关掉另一个面板。'],
  ['The iPhone has not produced a screen frame. Unlock it and retry.', 'iPhone 没有送出画面帧，请解锁后重试。'],
  ['Wait for a fresh physical iOS screen before sending input.', '等待 iPhone 的新画面后再输入。'],
  ['Tools', '工具'],
  ['Logs', '日志'],
  ['Performance', '性能'],
  ['Storage', '存储'],
  ['App Intel', '应用分析'],
  ['App Flow', '应用流程'],
  ['Testing', '测试'],
  ['Refresh', '刷新'],
  ['Screenshot', '截图'],
  ['Home', '主页'],
  ['App switcher', '应用切换'],
  ['Hide tools', '隐藏工具'],
  ['Select a device', '选择设备'],
  ['No devices', '没有设备'],
  ['Devices unavailable', '设备不可用'],
  ['Could not start the simulator backend.', '无法启动模拟器后端。'],
  ['Opening…', '正在打开…'],
]

const escapeForHTML = (text) => text.replace(/&/g, '&amp;').replace(/</g, '&lt;')

let changed = 0
for (const file of targets) {
  if (existsSync(file) === false) continue
  let html = readFileSync(file, 'utf8')
  const before = html
  for (const [english, chinese] of GLOSSARY) {
    if (html.includes(english) === false) continue
    // Titles/aria-labels are attributes; body copy is escaped text. Replace both
    // spellings, and leave camelCase identifiers (mobile-dev) alone by matching
    // only the human-readable spelling.
    html = html.split(english).join(chinese)
  }
  if (html !== before) {
    writeFileSync(file, html)
    changed += 1
    console.log(`localized ${file.slice(root.length + 1)}`)
  }
}
if (changed === 0) console.log('panel copy already localized')
